inputs = ['ziuy', 'kaj', 'uhyg', 'cz', 'ywuzxd']
outputs = ['hiuy', 'kaj', 'uhyg', 'ch', 'ywuhxd']

# Let me check which characters actually change
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Input {i}: '{inp}' -> Output {i}: '{outp}'")
    for j, (char_in, char_out) in enumerate(zip(inp, outp)):
        if char_in != char_out:
            print(f"  Position {j}: '{char_in}' -> '{char_out}'")

    # Check if there are length changes
    if len(inp) != len(outp):
        print(f"  Length change: {len(inp)} -> {len(outp)}")
    print()

# Check for characters that always change
all_chars_in = set(''.join(inputs))
all_chars_out = set(''.join(outputs))

print("All input chars:", sorted(all_chars_in))
print("All output chars:", sorted(all_chars_out))

# Check for consistent character mappings
mapping = {}
for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            if inp[i] not in mapping:
                mapping[inp[i]] = outp[i]
            else:
                print(f"Conflict: {inp[i]} maps to both {mapping[inp[i]]} and {outp[i]}")

print("Character mappings:", mapping)

